package android.view;public class ViewGroup extends View {public ViewGroup(){}public ViewGroup(android.content.Context c){super(c);}public java.util.List<View> children=new java.util.ArrayList<>();public int getChildCount(){return children.size();}public View getChildAt(int i){return children.get(i);}public void addView(View v){children.add(v);v.parent=this;}public void removeView(View v){children.remove(v);v.parent=null;}public void addView(View v,LayoutParams p){addView(v);v.setLayoutParams(p);}@Override public View findViewById(int id){if(this.id==id)return this;for(View v:children){View found=v.findViewById(id);if(found!=null)return found;}return null;}public static class LayoutParams {public static final int MATCH_PARENT=-1,WRAP_CONTENT=-2;public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}public static class MarginLayoutParams extends LayoutParams {public int leftMargin,topMargin,rightMargin,bottomMargin;private int start=Integer.MIN_VALUE,end=Integer.MIN_VALUE;public MarginLayoutParams(int w,int h){super(w,h);}public int getMarginStart(){return start==Integer.MIN_VALUE?leftMargin:start;}public int getMarginEnd(){return end==Integer.MIN_VALUE?rightMargin:end;}public void setMarginStart(int v){start=v;}public void setMarginEnd(int v){end=v;}}}
